import{_ as o,C as r,o as a,c as i,aj as e,E as c}from"./framework.js";const p=JSON.parse('{"title":"控制台：AI 配置 | Product / Console | Documentation","description":"控制台：AI 配置 in Kooboo: 配置组织级 AI Provider API Key。站点要使用 AI 能力时，通常先在这里准备 Provider，再回站点后台启用具体 AI 服务。","frontmatter":{"title":"控制台：AI 配置 | Product / Console | Documentation","description":"控制台：AI 配置 in Kooboo: 配置组织级 AI Provider API Key。站点要使用 AI 能力时，通常先在这里准备 Provider，再回站点后台启用具体 AI 服务。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/console/ai-config.html"}]]},"headers":[],"relativePath":"zh/product/console/ai-config.md","filePath":"product/console/ai-config.md","lastUpdated":1780996899000}'),n={name:"zh/product/console/ai-config.md"};function l(h,t,s,A,I,b){const d=r("DocImage");return a(),i("div",null,[t[0]||(t[0]=e('<h1 id="控制台-ai-配置" tabindex="-1">控制台：AI 配置 <a class="header-anchor" href="#控制台-ai-配置" aria-label="Permalink to &quot;控制台：AI 配置&quot;">​</a></h1><blockquote><p>配置组织级 AI Provider API Key。站点要使用 AI 能力时，通常先在这里准备 Provider，再回站点后台启用具体 AI 服务。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>菜单路径</td><td>顶部 <strong>控制台</strong> -&gt; 左侧 <strong>AI 配置</strong></td></tr><tr><td>深链</td><td><code>/_Admin/kconsole/consoleAIConfig</code></td></tr><tr><td>前端路由</td><td><code>/kconsole/consoleAIConfig</code></td></tr><tr><td>可见身份</td><td>组织管理员</td></tr></tbody></table><p>AI 配置是组织级入口，不是某个站点自己的配置页。它保存 Provider 的 API Key，供后续站点级 AI 服务使用。</p>',5)),c(d,{src:"/product/console/ai-config-overview.png",alt:"控制台 AI 配置 Provider 列表（ApiKey 已打码）",width:"1120"}),t[1]||(t[1]=e('<h2 id="页面结构" tabindex="-1">页面结构 <a class="header-anchor" href="#页面结构" aria-label="Permalink to &quot;页面结构&quot;">​</a></h2><p>页面会按 Provider 展示卡片，每张卡片包含：</p><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td>Provider 图标</td><td>后端返回的 Provider icon</td></tr><tr><td>Display Name</td><td>Provider 显示名称</td></tr><tr><td>模型标签</td><td>有聊天模型时显示 <code>Chat</code>；有向量模型时显示 <code>Embedded</code></td></tr><tr><td><code>ApiKey</code></td><td>当前 Provider 的自定义 API Key 输入框</td></tr><tr><td>底部保存栏</td><td>点击保存后统一提交所有 Provider 的 Key</td></tr></tbody></table><p>在线服务环境中，<code>ApiKey</code> 输入框旁会显示提示图标，用于说明空 Key 时的行为。</p><h2 id="配置-api-key" tabindex="-1">配置 API Key <a class="header-anchor" href="#配置-api-key" aria-label="Permalink to &quot;配置 API Key&quot;">​</a></h2><ol><li>找到要使用的 Provider。</li><li>在该 Provider 的 <code>ApiKey</code> 输入框中填入密钥。</li><li>点击页面底部保存按钮。</li><li>保存后页面会重新加载 Provider 列表。</li></ol><p>页面保存时会提交每个 Provider 的名称和 <code>ApiKey</code>。如果只改了其中一个 Provider，也会按当前页面状态统一提交。</p><h2 id="与站点-ai-服务的关系" tabindex="-1">与站点 AI 服务的关系 <a class="header-anchor" href="#与站点-ai-服务的关系" aria-label="Permalink to &quot;与站点 AI 服务的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控制台 AI 配置</th><th>CMS：AI 服务</th></tr></thead><tbody><tr><td>组织级 Provider Key</td><td>站点级 AI 功能开关、MCP、AI 函数</td></tr><tr><td>入口 <code>/_Admin/kconsole/consoleAIConfig</code></td><td>入口 <code>/_Admin/system/ai-service?SiteId={GUID}</code></td></tr><tr><td>先准备可用 Provider</td><td>再给具体站点选择和启用能力</td></tr></tbody></table><p>如果站点 AI 服务里调用模型失败，排查顺序通常是：余额 -&gt; 控制台 AI 配置 -&gt; 站点 AI 服务。</p><h2 id="常见工作流" tabindex="-1">常见工作流 <a class="header-anchor" href="#常见工作流" aria-label="Permalink to &quot;常见工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>顺序</th></tr></thead><tbody><tr><td>首次启用 AI</td><td><a href="./balance.html">余额</a> -&gt; AI 配置 -&gt; <a href="/kb-docs/zh/cms/settings/ai-service.html">CMS：AI 服务</a></td></tr><tr><td>更换 Provider Key</td><td>AI 配置 -&gt; 修改 <code>ApiKey</code> -&gt; 保存 -&gt; 回站点测试</td></tr><tr><td>只用 Kooboo 内置能力</td><td>先确认页面提示和环境支持，再决定是否填写自定义 Key</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./../console.html">控制台概述</a></td><td>控制台菜单地图</td></tr><tr><td><a href="./balance.html">余额</a></td><td>AI 使用前的账户余额核对</td></tr><tr><td><a href="/kb-docs/zh/cms/settings/ai-service.html">CMS：AI 服务</a></td><td>站点级 AI 服务、MCP、AI 函数</td></tr><tr><td><a href="./../ai-chat.html">AI Claw / AI Chat</a></td><td>站点后台 AI 入口</td></tr></tbody></table>',14))])}const m=o(n,[["render",l]]);export{p as __pageData,m as default};
